local config = {
  ui_story_31190101_1_dialog_content = "Navegador, Navegador!",
  ui_story_31190101_2_dialog_content = "Vice? Qual é o problema?",
  ui_story_31190101_X2_dialog_content = "Tá rolando algo sério!",
  ui_story_31190101_3_dialog_content = "Uma placa estranha apareceu no corredor!",
  ui_story_31190101_4_dialog_content = "Placa? De que tipo?",
  ui_story_31190101_5_dialog_content = "É... É de madeira.",
  ui_story_31190101_X5_dialog_content = "Com um símbolo enorme da Illumina.",
  ui_story_31190101_6_dialog_content = "E na parte de trás entalharam as palavras <color=#FFB400>\"Quem tiver coragem suficiente para desafiar a mais poderosa da Colossus toque nesta placa, se ousar!\"</color>.",
  ui_story_31190101_7_dialog_content = "Significa que... alguém na Colossus está procurando briga?",
  ui_story_31190101_8_dialog_content = "Não sei...",
  ui_story_31190101_9_dialog_content = "Mas pela minha experiência, parece que alguém está criando problemas novamente!",
  ui_story_31190101_11_dialog_content = "Viu? Bem aqui...",
  ui_story_31190101_12_dialog_content = "Sim… Estou vendo.",
  ui_story_31190101_13_dialog_content = "Seria algum tipo de desafio de alguém na Colossus?",
  ui_story_31190101_14_dialog_content = "Esse desafio... Pelo visto, vamos encarar alguns problemas!",
  ui_story_31190101_15_dialog_content = "Se rolar uma briga na Colossus, vai saber o tamanho do estrago que causaria!",
  ui_story_31190101_16_dialog_content = "E se estragarem as instalações da Colossus... Fico com dor de cabeça só de pensar nos custos dos reparos!",
  ui_story_31190101_17_dialog_content = "Navegador, nossas economias estão em jogo...",
  ui_story_31190101_18_dialog_content = "Vice, tenta relaxar um pouco...",
  ui_story_31190101_19_dialog_content = "Tó tentando! Mas fala sério, quem faria tal coisa na Colossus?!",
  ui_story_31190101_20_dialog_content = "Vice, ainda não aconteceu nada. Não se empolga...",
  ui_story_31190101_21_dialog_content = "Sua cauda está balançando pra todo lado!",
  ui_story_31190101_22_dialog_content = "Ei.... Que barulho foi esse?",
  ui_story_31190101_23_dialog_content = "Sua cauda... derrubou a placa.",
  ui_story_31190101_24_dialog_content = "Então foi você... Ousa desafiar a mais poderosa da Colossus, <color=#FFB400>Revy</color>?",
  ui_story_31190101_25_dialog_content = "Iiiihh!",
  ui_story_31190101_26_dialog_content = "Sim, Vice, a arqueira de cauda comprida, veio me desafiar, é isso?",
  ui_story_31190101_27_dialog_content = "Não, não, não...",
  ui_story_31190101_28_dialog_content = "Olha, Revy! Não quero desafiar ninguém! Minha cauda derrubou a placa acidentalmente, viu?",
  ui_story_31190101_29_dialog_content = "Espere... \"Me desafiar\"? Está dizendo que foi você quem colocou a placa?",
  ui_story_31190101_30_dialog_content = "Claro que fui eu.",
  ui_story_31190101_31_dialog_content = "Então, significa que... Revy, você é, ahn, a mais poderosa da Colossus?",
  ui_story_31190101_32_dialog_content = "Você também acha? Ah, mas é óbvio! Mentes heróicas pensam igual.",
  ui_story_31190101_33_dialog_content = "Hahaha... Então, está esperando que alguém venha te desafiar?",
  ui_story_31190101_34_dialog_content = "Isso ai, e você foi a primeira a tocar na placa de madeira.",
  ui_story_31190101_35_dialog_content = "Tudo bem... Mas Revy, você apareceu no instante que encostei nela!",
  ui_story_31190101_36_dialog_content = "Isso mesmo... Como sabia que Vice tocou na placa, pra começo de conversa?",
  ui_story_31190101_37_dialog_content = "É algum tipo de nova tecnologia da Illumina que desconhecemos?",
  ui_story_31190101_38_dialog_content = "Bem, me escondi ali e fique de tocaia na sombra...",
  ui_story_31190101_39_dialog_content = "De tocaia na sombra? Ou seja, ficou observando na surdina para ver que encostaria na sua placa...?",
  ui_story_31190101_40_dialog_content = "Exatamente... Foi assim tão óbvio?",
  ui_story_31190101_41_dialog_content = "E foi Vice quem tocou primeiro na placa de madeira.",
  ui_story_31190101_42_dialog_content = "Agora, Vice precisa me desafiar. Que o combate decida, de uma vez por todas, quem é a mais poderosa!",
  ui_story_31190101_43_dialog_content = "Mas Revy... Hum... Realmente foi um acidentezinho sem importância...",
  ui_story_31190101_44_dialog_content = "Mas você tocou nela mesmo assim.",
  ui_story_31190101_45_dialog_content = "Hum... Que tal a gente ignorar o desafio e concordar que você é a mais poderosa?",
  ui_story_31190101_46_dialog_content = "Isso não vale! Apenas pelo combate mortal posso provar que sou digna do título de \"A Mais Poderosa da Colossus\"!",
  ui_story_31190101_47_dialog_content = "Como me meti nessa confusão...?!",
  ui_story_31190101_48_dialog_content = "Preparada para começar nosso duelo predestinado?",
  ui_story_31190101_49_dialog_content = "Ahn, Revy... Que tal baixar sua arma e a gente conversar a respeito...?",
  ui_story_31190101_50_dialog_content = "Muito bem.",
  ui_story_31190101_51_dialog_content = "A questão é que todos nós que vivemos na Colossus estamos do mesmo lado. Não precisamos sair por aí nos desafiando...",
  ui_story_31190101_52_dialog_content = "E além disso... somos soldados da Illumina!",
  ui_story_31190101_53_dialog_content = "Soldados também precisam aperfeiçoar suas habilidade de luta entre si",
  ui_story_31190101_54_dialog_content = "E isso vale ainda mais para soldados da linha de frente! Devemos nos fortalecer com o sangue fresco e as chamas ardentes da batalha!",
  ui_story_31190101_55_dialog_content = "Ahn? Está dizendo que quer me fazer... sangrar?!",
  ui_story_31190101_56_dialog_content = "Estava pensando nisso.",
  ui_story_31190101_57_dialog_content = "Acho que devemos poupar nossas forças para lutar juntas contra Eclipsitas...",
  ui_story_31190101_58_dialog_content = "Seria uma maneira melhor de nos fortalecer em vez dessa sua competição... O que acha?",
  ui_story_31190101_59_dialog_content = "Não nego que há alguma verdade no que diz, mas não vejo mal algum em promover alguma competição saudável.",
  ui_story_31190101_60_dialog_content = "Vocês duas, que tal a gente dar um tempo e falar nisso depois?",
  ui_story_31190101_61_dialog_content = "Intervalo! Intervalo!",
  ui_story_31190101_62_dialog_content = "Competição! Erro! Erro!",
  ui_story_31190101_63_dialog_content = "Competição, confirmada!",
  ui_story_31190101_64_dialog_content = "Incorreto! Erro! Iniciando reparos!",
  ui_story_31190101_65_dialog_content = "Consertar erro de mecanismo! Consertar erro de mecanismo!",
  ui_story_31190101_66_dialog_content = "Essa não... são os vagalumes.",
  ui_story_31190101_67_dialog_content = "Agora os sons de suas gravações e do sistema estão embaralhados. Que baderna...",
  ui_story_31190101_68_dialog_content = "Parem com isso?! Estão me dando dor de cabeça!",
  ui_story_31190101_69_dialog_content = "Navegador! Não quero dar dor de cabeça a ninguém.. Só estávamos discutindo algo óbvio. Aliados nunca devem lutar!",
  ui_story_31190101_70_dialog_content = "Já devia saber que detesto discutir...",
  ui_story_31190101_71_dialog_content = "E lutar? Eu falei que devíamos apenas participar de uma competição amigável. Embora alguns possam dizer que dá na mesma.",
  ui_story_31190101_72_dialog_content = "É a mesma coisa! Especialmente quando se trata de sangue!",
  ui_story_31190101_73_dialog_content = "Hum? É mesmo? Talvez... Mas não é nada disso.",
  ui_story_31190101_74_dialog_content = "Ei, eu não estava falando de vocês duas!",
  ui_story_31190101_75_dialog_content = "Vocês duas! Vocês duas!",
  ui_story_31190101_76_dialog_content = "(Que pesadelo... As coisas estão ficando fora de controle aqui...)",
  ui_story_31190101_77_dialog_content = "(É isso!)",
  ui_story_31190101_X77_dialog_content = "(Sempre desmaio, certo? Posso fazer isso para acabar com essa baderna!)",
  ui_story_31190101_78_dialog_content = "Vice... Revy... Parem de discutir...",
  ui_story_31190101_79_dialog_content = "Eu...",
  ui_story_31190101_80_dialog_content = "Essa não! Navegador! Navegador! Você desmaiou?!",
  ui_story_31190101_81_dialog_content = "Minha poderosa presença foi demais para o fraco Navegador?",
  ui_story_31190101_82_dialog_content = "<color=#e8d9bb>Vice e Reventon levam você até seu quarto...</color>",
  ui_story_31190101_83_dialog_content = "<color=#e8d9bb>Algumas horas depois...</color>",
  ui_story_31190101_84_dialog_content = "Caramba... Deu certo.",
  ui_story_31190101_85_dialog_content = "E impedi que uma briga danificasse nossa Colossus...",
  ui_story_31190101_86_dialog_content = "Hã? Quem?",
  ui_story_31190101_87_dialog_content = "Sou eu. Vejo que acordou.",
  ui_story_31190101_88_dialog_content = "Ah... Entre.",
  ui_story_31190101_89_dialog_content = "Melhorou?",
  ui_story_31190101_90_dialog_content = "Mais ou menos.",
  ui_story_31190101_91_dialog_content = "Então você desmaiou porque eu queria participar de um duelo e lutar a bordo da Colossus... É isso?",
  ui_story_31190101_92_option_content = "Não foi por isso!",
  ui_story_31190101_93_dialog_content = "Sério? Mas foi só falar em lutar e você apagou.",
  ui_story_31190101_94_option_content = "Correto.",
  ui_story_31190101_95_dialog_content = "Como eu suspeitava.",
  ui_story_31190101_96_dialog_content = "Bem, retirei a placa de madeira.",
  ui_story_31190101_97_dialog_content = "Desde que eu não promova outro desafio, você não desmaia novamente, certo?",
  ui_story_31190101_98_dialog_content = "Sim, isso mesmo!",
  ui_story_31190101_99_dialog_content = "Hum. Entendi.",
  ui_story_31190101_100_dialog_content = "Bem, vou me retirar.",
  ui_story_31190101_101_dialog_content = "<color=#e8d9bb>Alguns dias depois.</color>",
  ui_story_31190101_102_dialog_content = "*Tocando*",
  ui_story_31190101_103_dialog_content = "Ainda não tá no intervalo do almoço? Sonhei que um alarme estava tocando...",
  ui_story_31190101_104_dialog_content = "Luzes de vagalumes...? Significa que...",
  ui_story_31190101_105_dialog_content = "Não estou sonhando!",
  ui_story_31190101_106_dialog_content = "O que houve?",
  ui_story_31190101_107_dialog_content = "Salão! Falha ao consertar saco de areia! Salão! Falha ao consertar saco de areia!",
  ui_story_31190101_108_dialog_content = "Ufa... Pelo que posso ver, Soroz continua intacto...",
  ui_story_31190101_109_dialog_content = "É melhor dar uma olhada no Salão.",
  ui_story_31190101_110_dialog_content = "<color=#e8d9bb>Um som alto vem do Salão</color>.",
  ui_story_31190101_111_dialog_content = "Agora, a <color=#FFB400>Assembleia de Extermínio de Eclipsitas</color> entra em sua sessão interativa final.",
  ui_story_31190101_112_dialog_content = "Você ai, explique como faria para matar um Eclipsita e demonstre seu método nesse saco de areia.",
  ui_story_31190101_113_dialog_content = "Como acabei de mostrar.",
  ui_story_31190101_114_dialog_content = "Ha! Já atropelei um Eclipsita com um caminhão blindado!",
  ui_story_31190101_X114_dialog_content = "Desse jeito!",
  ui_story_31190101_115_dialog_content = "Já sentiu o cheiro do sumo de um Eclipsita? Não é para qualquer um!",
  ui_story_31190101_116_dialog_content = "Saco de areia, saco explodiu e a areia se espalhou... Tentando consertar! Tentando consertar!",
  ui_story_31190101_117_dialog_content = "Costumo usar minha magia para matar essas coisas.",
  ui_story_31190101_118_dialog_content = "Fecham os olhos e morrem. Me parece um método bastante simples e objetivo.",
  ui_story_31190101_X118_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_31190101_119_dialog_content = "Saco de areia solto! Tentando consertar! Tentando consertar!",
  ui_story_31190101_120_dialog_content = "Eclipsitas? Apenas pego minha arma e aperto o gatilho até fazer... \"clique\". Hehe...",
  ui_story_31190101_121_dialog_content = "Saco de areia, vazamento de areia detectado! Tentando consertar! Tentando consertar!",
  ui_story_31190101_122_dialog_content = "Na época, eu e a galera avançamos sobre hordas dessas coisas sem sofrer um arranhão...",
  ui_story_31190101_123_dialog_content = "Atacamos tão rápido que essas coisas ficaram alguns segundos sem saber o que estava rolando! Então veio a correria... Tsc...",
  ui_story_31190101_124_dialog_content = "Sacos de areia consertados com sucesso! Nenhum rasgo detectado!",
  ui_story_31190101_X124_dialog_content = "Ha!",
  ui_story_31190101_125_dialog_content = "Saco de areia, saco de areia destruído! Falha nos concertos! Falha nos concertos!",
  ui_story_31190101_126_dialog_content = "Fiz um registro oficial de suas contribuições. Vocês compartilharam 265 maneiras diferentes de matar Eclipsitas.",
  ui_story_31190101_127_dialog_content = "Todos parecem satisfeitos por enquanto. Continuaremos nossa colaboração uma próxima vez.",
  ui_story_31190101_128_dialog_content = "E assim declaro este encontro encerrado!",
  ui_story_31190101_129_dialog_content = "Por sorte, parece que estavam... debatendo alguma coisa...",
  ui_story_31190101_130_dialog_content = "<color=#e8d9bb>Após voltar ao seu quarto...</color>",
  ui_story_31190101_131_dialog_content = "Vinte sacos de areia detonados.",
  ui_story_31190101_132_dialog_content = "<anim type=Shake><size=45>Vinte sacos de areia detonados!</size></anim>",
  ui_story_31190101_133_dialog_content = "Eu sei...",
  ui_story_31190101_134_dialog_content = "Devia estar feliz por só isso ter sido detonado!",
  ui_story_31190101_135_dialog_content = "Desencana. Desde que não comecem a lutar na Colossus, posso aceitar na boa vinte sacos de areia detonados.",
  ui_story_31190101_136_dialog_content = "<color=#e8d9bb>No dia seguinte.</color>",
  ui_story_31190101_137_dialog_content = "Hum... Está ai?",
  ui_story_31190101_138_dialog_content = "Sim. O que foi, Revy?",
  ui_story_31190101_139_dialog_content = "Seus vaga-lumes transmitiram repetidamente... minhas façanhas... por toda Colossus ontem.",
  ui_story_31190101_140_dialog_content = "Façanhas?",
  ui_story_31190101_141_dialog_content = "Os sacos de areia detonados.",
  ui_story_31190101_142_dialog_content = "Me desculpe.",
  ui_story_31190101_143_dialog_content = "Destruímos vinte sacos de areia ontem. Se Vice não tivesse nos detido, mais sacos teriam sofrido o mesmo destino.",
  ui_story_31190101_144_dialog_content = "Isso não está certo. Esse pedido de desculpas não convence. Antes de vir para cá, perguntei para Vice como pedir desculpas sinceras.",
  ui_story_31190101_145_dialog_content = "Aham... sinto muito mesmo pelo grande dano causado ontem a você e à Colossus, Navegador, sinceramente.",
  ui_story_31190101_146_dialog_content = "Não precisa ser tão formal...",
  ui_story_31190101_147_dialog_content = "Não foi grande coisa. Desde que você não brigue na Colossus, o resto não me incomoda.",
  ui_story_31190101_148_dialog_content = "Sério?",
  ui_story_31190101_149_dialog_content = "Quando diz não ser grande coisa, significa que não está zangado?",
  ui_story_31190101_150_option_content = "É claro.",
  ui_story_31190101_151_dialog_content = "Você compreendeu minhas intenções, pelo visto!",
  ui_story_31190101_152_option_content = "Sinceramente, estou um pouco zangado...",
  ui_story_31190101_153_dialog_content = "Então, por favor, pode desencadear sua fúria sobre mim.",
  ui_story_31190101_154_dialog_content = "Não pretendíamos danificar sua Colossus. Só queria provar...",
  ui_story_31190101_155_dialog_content = "Eu sei.",
  ui_story_31190101_156_dialog_content = "Provar que realmente sou a mais poderosa da Colossus...",
  ui_story_31190101_157_dialog_content = "De qualquer forma, aliados nunca devem lutar entre si... especialmente na Colossus!",
  ui_story_31190101_158_dialog_content = "Cumprir isso, eu devo... provavelmente.",
  ui_story_31190101_159_dialog_content = "<color=#e8d9bb>Um dia depois, durante a aterrizagem de Soroz...</color>",
  ui_story_31190101_160_dialog_content = "Ahn? Tem algo na porta.",
  ui_story_31190101_161_dialog_content = "Assinado - Mestra do Lâminaltar, Mecânica Soberana e Vanguarda Suprema da Colossus: Revy.",
  ui_story_31190101_162_dialog_content = "Vejamos o que temos aqui...",
  ui_story_31190101_163_dialog_content = "Eca! Que cheiro horrível é esse?",
  ui_story_31190101_164_dialog_content = "Tem um bilhete dentro...",
  ui_story_31190101_165_dialog_content = "\"Já que não posso desafiar meus aliados e nem lutar na Colossus...\"",
  ui_story_31190101_166_dialog_content = "\"Assim que pousarmos, desafiarei o líder dos meus aliados, o Celestita!\"",
  ui_story_31190101_167_dialog_content = "Argh, sinto que vou desmaiar de novo por causa desse cheiro...",
  ui_story_31190101_X167_dialog_content = "...",
  ui_story_31190101_168_dialog_content = "Sinceramente, considerando o desafio da Revy, talvez desmaiar seria o ideal no momento...",
  ui_story_31190601_1_dialog_content = "Graças a você, conseguimos identificar o ladrão em pouco tempo.",
  ui_story_31190601_2_dialog_content = "Sua ajuda é muito apreciada. Fique tranquilo, ele vai ter o castigo que merece...",
  ui_story_31190601_3_dialog_content = "Eu estava apenas fazendo o que eu sentia que deveria. Estou sempre feliz em ajudar!",
  ui_story_31190601_4_dialog_content = "<color=#e8d9bb>Bate, baque, baque!</color>",
  ui_story_31190601_5_dialog_content = "Huh? O que foi aquele barulho?",
  ui_story_31190601_6_dialog_content = "Parecia alguém – não, como se algumas pessoas tivessem caído no chão.",
  ui_story_31190601_7_dialog_content = "Ah, deve ser o novo garoto de novo. Eu juro, desde que ela chegou aqui, parece que nunca para...",
  ui_story_31190601_8_dialog_content = "O \"novo garoto\"? Eu não acho que uma criança poderia estar fazendo esse tipo de barulho...",
  ui_story_31190601_9_dialog_content = "Heh, eu também não acreditaria se não tivesse visto por mim mesmo.",
  ui_story_31190601_10_dialog_content = "No dia em que ela chegou, fui até a cela dela para entregar a refeição. Na época, tudo parecia perfeitamente normal.",
  ui_story_31190601_11_dialog_content = "Mas quando voltei para pegar sua bandeja, todos os outros na cela tinham sido nocauteados por aquele pirralho maluco.",
  ui_story_31190601_12_dialog_content = "E enquanto eles jaziam inconscientes por todo o chão, ela estava sentada ao lado, comendo suas refeições como se nada tivesse acontecido.",
  ui_story_31190601_13_dialog_content = "Suspiro... Nós a mudamos 16 vezes até agora. Nesse ritmo, o único lugar para ela será o confinamento solitário.",
  ui_story_31190601_14_dialog_content = "Espere, você está me dizendo... Uma garotinha lutou e venceu todos os condenados em 15 celas de prisão?!",
  ui_story_31190601_15_dialog_content = "(Uma garotinha insanamente poderosa que adora lutar... tenho um mau pressentimento sobre isso...)",
  ui_story_31190601_16_dialog_content = "Isso mesmo, e é por isso que eu deveria realmente dar uma olhada no que aconteceu desta vez.",
  ui_story_31190601_17_dialog_content = "Desculpe, mas você terá que se ver fora. Você sabe onde é a saída, certo?",
  ui_story_31190601_18_dialog_content = "Er, se não for muito incômodo... Posso ir com você?",
  ui_story_31190601_19_dialog_content = "Comigo?",
  ui_story_31190601_20_dialog_content = "P-Por favor, não entenda errado! Eu prometo que não estou tramando nada!",
  ui_story_31190601_21_dialog_content = "É só que tenho a sensação de que posso ajudá-lo com isso.",
  ui_story_31190601_22_dialog_content = "Bem... Arrase, garoto.",
  ui_story_31190601_23_dialog_content = "Especialmente porque você já nos ajudou um monte e tudo. Se alguém perguntar, direi apenas que fizemos um desvio rápido na saída.",
  ui_story_31190601_24_dialog_content = "Mas nada de engraçado, entendeu? Caso contrário, é a minha cabeça no cepo.",
  ui_story_31190601_25_dialog_content = "Sim!",
  ui_story_31190601_26_dialog_content = "Não me diga que não há outras células sobrando?",
  ui_story_31190601_27_dialog_content = "Esta foi uma decepção maior do que eu pensava... Será que eu já poderia ter ficado muito mais forte?",
  ui_story_31190601_28_dialog_content = "(Espere, isso soa como...)",
  ui_story_31190601_29_dialog_content = "Reviu?!",
  ui_story_31190601_30_dialog_content = "Huh? Ah, ei PlayerName! Você também foi preso?",
  ui_story_31190601_31_dialog_content = "Vocês dois se conhecem?",
  ui_story_31190601_32_dialog_content = "Sim... Um pouco, na verdade...",
  ui_story_31190601_33_dialog_content = "Você sabe, eu sempre considerei você como o tipo de herói bonzinho, como o personagem principal de uma história em quadrinhos. Nunca pensei que veria você na cadeia algum dia!",
  ui_story_31190601_34_dialog_content = "Mas já que você está aqui... Acho que não tenho escolha a não ser nocautear você também.",
  ui_story_31190601_35_dialog_content = "Eu não fui preso de jeito nenhum! Só vim identificar um suspeito de um assalto.",
  ui_story_31190601_36_dialog_content = "Espere um segundo. Você bateu em todos esses condenados aqui... sozinho?",
  ui_story_31190601_37_dialog_content = "Isso mesmo!",
  ui_story_31190601_38_dialog_content = "Então o guarda não estava brincando... Você espancou seriamente todos os prisioneiros da cadeia inteira sozinho?!",
  ui_story_31190601_39_dialog_content = "Sim, mas esses caras não eram tão divertidos quanto os das últimas quinze celas. Eu mal toquei neles antes que eles caíssem direto no chão!",
  ui_story_31190601_40_dialog_content = "Inacreditável... Nem uma única pessoa nesta maldita prisão de Umbraton sabe lutar!",
  ui_story_31190601_41_dialog_content = "T-Esta instalação destina-se apenas a abrigar pequenos criminosos! Mas, a julgar pelos últimos dois dias, acho que este também não é o lugar certo para você...",
  ui_story_31190601_42_dialog_content = "Huh? Você está me deixando ir, então?",
  ui_story_31190601_43_dialog_content = "Nos seus sonhos! Em apenas dois dias, você conseguiu dar uma surra em todos os presos deste lugar!",
  ui_story_31190601_44_dialog_content = "A princípio, pensei que era porque você não se dava bem com os prisioneiros da primeira cela. Mas acontece que você tinha um osso para escolher com cada pessoa em todo o maldito lugar!",
  ui_story_31190601_45_dialog_content = "Se você não encontrar uma desculpa melhor para toda essa briga, não terei escolha a não ser transferi-lo para a solitária.",
  ui_story_31190601_46_dialog_content = "...",
  ui_story_31190601_47_dialog_content = "Última chance, garoto – por que você começou uma briga com cada um de seus companheiros de cela?",
  ui_story_31190601_48_dialog_content = "(Ela continua olhando para mim... Existe algo que ela não pode dizer ao guarda?)",
  ui_story_31190601_49_dialog_content = "S-Senhor? Podemos ter um momento para conversar em particular?",
  ui_story_31190601_50_dialog_content = "Eu só preciso de dez minutos. Por favor, confie em mim!",
  ui_story_31190601_51_dialog_content = "Você pode ficar de olho em nós do outro lado da cela. Eu prometo que não vou quebrar nenhuma lei!",
  ui_story_31190601_52_dialog_content = "... Multar. Eu tenho que ligar para o médico da prisão aqui, de qualquer maneira.",
  ui_story_31190601_53_dialog_content = "Há guardas postados na porta também, então nem tente escapar.",
  ui_story_31190601_54_dialog_content = "Obrigado pela confiança, senhor.",
  ui_story_31190601_55_dialog_content = "O guarda já se foi, Revy. Eu acho que você pode falar livremente agora.",
  ui_story_31190601_56_dialog_content = "A-Sobre o quê? Eu não faço ideia do que você está falando...",
  ui_story_31190601_57_dialog_content = "Estou falando sobre o motivo pelo qual você começou uma briga na prisão!",
  ui_story_31190601_58_dialog_content = "Eles vão prendê-lo sozinho se você não contar a verdade!",
  ui_story_31190601_59_dialog_content = "... Tudo bem, mas só estou lhe dizendo.",
  ui_story_31190601_60_dialog_content = "Já que isso importa tanto para você... eu estava apenas <color=#FFB400>jogando pelas regras da prisão</color>, isso é tudo.",
  ui_story_31190601_61_dialog_content = "\"Regras da prisão\"...?",
  ui_story_31190601_62_dialog_content = "Sim!",
  ui_story_31190601_63_dialog_content = "Veja, não há loja na prisão. Você não pode simplesmente comprar o que quiser.",
  ui_story_31190601_64_dialog_content = "Se você realmente quer algo aqui, você pega de outra pessoa... À força, se necessário.",
  ui_story_31190601_65_dialog_content = "E isso são as regras da prisão, em poucas palavras.",
  ui_story_31190601_66_dialog_content = "Se for esse o caso, por que não disse ao guarda? Tenho certeza que ele já viu tudo.",
  ui_story_31190601_67_dialog_content = "Agora não é o momento certo para dizer a ele. Ainda estou super frustrado e irritado.",
  ui_story_31190601_68_dialog_content = "Por que razão? Revy, você mandou todos aqui esparramados. Você não conseguiu o que queria?",
  ui_story_31190601_69_dialog_content = "É isso mesmo! Eu venci todos eles, cada um! Isso é que é tão irritante.",
  ui_story_31190601_70_dialog_content = "Mas meu alvo e minha razão para ir para a cadeia em primeiro lugar ainda nem chegaram! Ainda não consegui o que vim buscar!",
  ui_story_31190601_71_dialog_content = "<size=45>Você se mandou para a cadeia só para poder recuperar alguma coisa?!</size>",
  ui_story_31190601_72_dialog_content = "O que diabos é tão importante que você iria voluntariamente para a prisão por isso?!",
  ui_story_31190601_73_dialog_content = "Bem, já que é você, acho que posso te dizer, PlayerName.",
  ui_story_31190601_74_dialog_content = "É um tesouro lendário, que inúmeras pessoas perseguiram. Um tesouro que superou até mesmo o maior dos guerreiros da história!",
  ui_story_31190601_75_dialog_content = "Apenas uma cheirada fará o couro cabeludo de qualquer pessoa formigar e queimar...",
  ui_story_31190601_76_dialog_content = "E apenas um gosto fará toda a sua cabeça ficar vermelha e suada...",
  ui_story_31190601_77_dialog_content = "Mas mesmo assim, as pessoas não podem resistir ao seu poder e continuarão a devorá-lo como um bando de viciados enlouquecidos...",
  ui_story_31190601_78_dialog_content = "E-Espere um minuto!",
  ui_story_31190601_79_dialog_content = "O que você está descrevendo parece muito perigoso...",
  ui_story_31190601_80_dialog_content = "Tem certeza que sabe o que está fazendo?!",
  ui_story_31190601_81_dialog_content = "O que você está dizendo? estou falando sobre o <color=#FFB400>Molho Quente Super Ardente</color>!",
  ui_story_31190601_82_dialog_content = "Huh? Você estava falando sobre molho picante?",
  ui_story_31190601_83_dialog_content = "O que mais poderia ser? Há apenas uma coisa que corresponde à minha descrição, e isso é Super Blazing Hot Sauce.",
  ui_story_31190601_84_dialog_content = "Você vê, \"picante\" não é apenas um sabor. É um tipo de dor.",
  ui_story_31190601_85_dialog_content = "Comer alimentos picantes faz com que seu corpo produza constantemente adrenalina e outras endorfinas, que por sua vez fazem você sentir excitação e satisfação.",
  ui_story_31190601_86_dialog_content = "Com essas coisas, você poderá seguir em frente mesmo depois que sua língua ficar totalmente dormente!",
  ui_story_31190601_87_dialog_content = "Ah, quanto mais eu falo sobre isso, mais eu quero provar sua delícia chocante... Eu quero tanto!",
  ui_story_31190601_88_dialog_content = "Então, a razão pela qual você espancou todos esses prisioneiros... foi apenas para colocar as mãos em um molho especial?",
  ui_story_31190601_89_dialog_content = "Em primeiro lugar, chama-se <color=#FFB400>Molho Quente Super Ardente</color>.",
  ui_story_31190601_90_dialog_content = "Em segundo lugar, acabei de lhe dizer que inúmeras pessoas sempre sonharam em tê-lo! Eu faria qualquer coisa só para colocar minhas mãos em alguns!",
  ui_story_31190601_91_dialog_content = "Quer dizer, eu acredito em você aí... Afinal, você estava até disposto a ir para a cadeia por isso. Eu me pergunto se Vovó já ouviu falar de...",
  ui_story_31190601_92_dialog_content = "<size=45>Pare!!!</size>",
  ui_story_31190601_93_dialog_content = "Ele, uh... não sabe que estou aqui.",
  ui_story_31190601_94_dialog_content = "Eu estava ajudando a vovó a comprar alguns ingredientes em Umbraton quando ouvi algumas pessoas falando sobre molho picante.",
  ui_story_31190601_95_dialog_content = "Não pude evitar, então fui até lá para ouvir mais. Eu nunca esperei ouvi-los mencionar <color=#FFB400>Molho Quente Super Ardente</color> no entanto.",
  ui_story_31190601_96_dialog_content = "Um deles disse que é servido quase exclusivamente nas prisões.",
  ui_story_31190601_97_dialog_content = "Com seu sabor poderoso, uma única gota é tudo o que você precisa para uma tigela inteira de comida. Originalmente, foi especialmente concebido como o melhor tempero para refeições na prisão.",
  ui_story_31190601_98_dialog_content = "Como resultado de seu sabor incrível, tornou-se uma forma de moeda forte dentro do sistema prisional.",
  ui_story_31190601_99_dialog_content = "Com apenas uma garrafa de <color=#FFB400>Molho Quente Super Ardente</color>, uma pessoa poderia trocá-lo por qualquer coisa que quisesse na prisão.",
  ui_story_31190601_100_dialog_content = "Mas mesmo depois de bater a luz do dia em todos esses prisioneiros, ainda não vi nem uma gota da coisa...",
  ui_story_31190601_101_dialog_content = "Já se passaram dez minutos! Sua pequena \"visita\" acabou agora.",
  ui_story_31190601_102_dialog_content = "Chegou a tempo, senhor!",
  ui_story_31190601_103_dialog_content = "Eu não consegui encontrar o que eu queria aqui, então você pode me deixar ir agora.",
  ui_story_31190601_104_dialog_content = "Bem, dado o quão pequeno seu crime foi em primeiro lugar, eu poderia ter deixado você ir já...",
  ui_story_31190601_105_dialog_content = "Mas depois de ver você espancar todos os prisioneiros que temos neste lugar, temo que você tenha que ficar mais um pouco.",
  ui_story_31190601_106_dialog_content = "<size=45>O que?! Você está brincando comigo?!</size>",
  ui_story_31190601_107_dialog_content = "Agora que estamos no assunto, o que exatamente você fez para ser jogado na cadeia, Revy?",
  ui_story_31190601_108_dialog_content = "Não queria infringir a lei nem nada... Só queria entrar aqui.",
  ui_story_31190601_109_dialog_content = "Então eu parei na frente de um patrulheiro, puxei um sinal de trânsito do chão e depois o coloquei de volta no lugar algumas vezes.",
  ui_story_31190601_110_dialog_content = "Depois disso, eles me acusaram de vandalismo de patrimônio público e me jogaram aqui.",
  ui_story_31190601_111_dialog_content = "Acho que isso explica muito sobre a natureza dos crimes dos condenados aqui...",
  ui_story_31190601_112_dialog_content = "Tenho de transportar todos estes prisioneiros para a enfermaria. Esta noite, tens de te sentar aqui sozinho e pensar no que fizeste.",
  ui_story_31190601_113_dialog_content = "E-Espere, senhor. Só por curiosidade, você já ouviu falar de um certo... molho picante super apimentado?",
  ui_story_31190601_114_dialog_content = "É chamado <color=#FFB400>Molho Quente Super Ardente</color>!",
  ui_story_31190601_115_dialog_content = "Y-Sim, isso. Ouvi dizer que tem um gosto incrível e que é usado como uma espécie de moeda forte nas prisões.",
  ui_story_31190601_116_dialog_content = "Que molho, agora? Nunca ouvi falar de nada do tipo.",
  ui_story_31190601_117_dialog_content = "Além disso, as prisões de Umbraton usam carne enlatada como moeda forte.",
  ui_story_31190601_118_dialog_content = "<size=45>O que?!?</size>",
  ui_story_31190601_119_dialog_content = "Mas como isso poderia ser...? Como poderia uma prisão não ter meu lendário molho picante...?",
  ui_story_31190601_120_dialog_content = "... Você está bem, Revy?",
  ui_story_31190601_121_dialog_content = "Parece que sua alma te deixou...",
  ui_story_31190601_122_dialog_content = "Eu... eu vou ficar bem...",
  ui_story_31190601_123_dialog_content = "PlayerName... Eu realmente poderia ir para um pouco da comida caseira da Vovó agora ...",
  ui_story_31190601_124_option_content = "Não se preocupe. Vou ver o que posso fazer para te tirar daqui!",
  ui_story_31190601_125_dialog_content = "É, senhor? Você disse que o crime dela foi leve o suficiente para deixá-la ir já, certo?",
  ui_story_31190601_126_dialog_content = "Além disso, sua pequena briga com os outros prisioneiros deve ser considerada parte das \"regras da prisão\" não ditas aqui.",
  ui_story_31190601_127_dialog_content = "Existe alguma chance de você...",
  ui_story_31190601_128_dialog_content = "Não. Mas eu vou deixar você saber imediatamente quando ela estiver livre para ir.",
  ui_story_31190601_129_dialog_content = "E-eu vejo... Desculpe, Revy. Está fora das minhas mãos.",
  ui_story_31190601_130_option_content = "Desculpe, não posso ajudá-lo a sair.",
  ui_story_31190601_131_dialog_content = "Quero dizer, criminosos ou não, você atacou todas essas pessoas...",
  ui_story_31190601_132_dialog_content = "M-Mas não se preocupe! Vou me certificar de trazer um pouco da comida de Gram assim que eles te deixarem sair!",
  ui_story_31190601_133_dialog_content = "Suspiro... eu sabia. Acho que você realmente não pode contar com ninguém além de você mesmo, hein?",
  ui_story_31190601_134_dialog_content = "Ainda bem que comecei a me preparar para este dia anos atrás.",
  ui_story_31190601_135_dialog_content = "Que tipo de pessoa se prepara para estar na cadeia um dia?",
  ui_story_31190601_136_dialog_content = "Isso não é importante. O importante é que passei os últimos cinco anos me preparando para o caso de precisar sair da prisão.",
  ui_story_31190601_137_dialog_content = "Parece que finalmente é hora de colocar \"aquele\" movimento em bom uso ...",
  ui_story_31190601_138_dialog_content = "<color=#e8d9bb>Bate, baque, baque...</color>",
  ui_story_31190601_139_dialog_content = "Ué, Revy? O que você está fazendo naquele canto ali?",
  ui_story_31190601_140_dialog_content = "Isso soa muito como... <size=45>A-Você está cavando um túnel?!</size>",
  ui_story_31190601_141_dialog_content = "Shhh!!! Mantenha-o para baixo, você vai?!",
  ui_story_31190601_142_dialog_content = "Eu fiz as contas. Se eu começar a cavar agora, devo voltar para Gannon City em pouco menos de dez anos.",
  ui_story_31190601_143_dialog_content = "Quando eu finalmente cavar meu caminho para a liberdade, até os poderes lá em cima ficarão impressionados!",
  ui_story_31190601_144_dialog_content = "E quando esse dia glorioso chegar, vou erguer esta lâmina que me ajudou a escapar, olhar para a chuva torrencial e gritar para os céus—",
  ui_story_31190601_145_dialog_content = "Mas o guarda ainda está aqui, Revy. Ele tem observado você cavar esse tempo todo.",
  ui_story_31190601_146_dialog_content = "Hã?",
  ui_story_31190601_147_dialog_content = "Também... Tenho certeza que ele ouviu tudo o que você acabou de dizer.",
  ui_story_31190601_148_dialog_content = "Cavar, por tudo que eu me importo.",
  ui_story_31190601_149_dialog_content = "Há muitos prisioneiros aqui que querem cavar sua saída. Você não é o primeiro e com certeza não será o último.",
  ui_story_31190601_150_dialog_content = "A maioria deles desiste depois de cerca de três dias, no entanto. O máximo que vi um prisioneiro continuar foi uma semana, e mesmo assim... O \"túnel\" que eles cavaram era apenas um buraco de um metro de profundidade.",
  ui_story_31190601_151_dialog_content = "Uau... Eles desistiram porque era uma tarefa muito difícil?",
  ui_story_31190601_152_dialog_content = "Quero dizer, não realmente. Como eu disse, este lugar é apenas para manter pequenos criminosos. Normalmente, só os seguramos por uma semana antes de soltá-los.",
  ui_story_31190601_153_dialog_content = "Então eu estou preso aqui por uma semana inteira...?",
  ui_story_31190601_154_dialog_content = "Isso não será necessário. Já solicitei um documento especial de liberação do Shadowlord. Você pode vir comigo agora.",
  ui_story_31190601_155_dialog_content = "Allura! Você veio para me salvar!",
  ui_story_31190601_156_dialog_content = "Sim! Eu sabia que não deveria ficar presa em um lugar como este para sempre!",
  ui_story_31190601_157_dialog_content = "Allura? O que você está fazendo aqui, de todos os lugares?",
  ui_story_31190601_158_dialog_content = "Se quer saber...",
  ui_story_31190601_159_dialog_content = "<color=#e8d9bb>Dois dias atrás</color>",
  ui_story_31190601_160_dialog_content = "Você precisa de algo, Gram? Ou por acaso você me encontrou uma antiguidade rara em Gannon City?",
  ui_story_31190601_161_dialog_content = "Não, isso é sobre Revy.",
  ui_story_31190601_162_dialog_content = "Revy? O que aconteceu?",
  ui_story_31190601_163_dialog_content = "Nada! Bem, ainda não, de qualquer maneira. Eu a vi sair esta manhã, mas ela estava vestida completamente diferente do habitual.",
  ui_story_31190601_164_dialog_content = "Eu a segui até a porta, apenas para vê-la pegar uma carona em um trem de suprimentos em direção a Umbraton. Você se importaria de ficar de olho naquele garoto para mim?",
  ui_story_31190601_165_dialog_content = "Por que não vem aqui você mesmo? Você não está curioso para ver o que ela está fazendo?",
  ui_story_31190601_166_dialog_content = "Já que ela mesma não me contou, ela não queria que eu soubesse. Não sou do tipo que faz nada desnecessário.",
  ui_story_31190601_167_dialog_content = "Ela é livre para fazer o que quiser. Tudo o que me importa é ter certeza de que ela está segura.",
  ui_story_31190601_168_dialog_content = "Entendido. Eu vou cuidar dela.",
  ui_story_31190601_169_dialog_content = "Eu te vi em Umbraton logo depois que terminei minha conversa com Vovó.",
  ui_story_31190601_170_dialog_content = "Então por que você não apareceu antes?! Achei que ia ficar preso aqui por uma semana!",
  ui_story_31190601_171_dialog_content = "Para começar, quando te vi incomodando aquele patrulheiro com um sinal de trânsito... Sinceramente, quis fingir que nem te conhecia.",
  ui_story_31190601_172_dialog_content = "Além disso, eu tinha assuntos muito mais urgentes na época. Eu teria perdido uma oportunidade única na vida de ver uma antiguidade única se tivesse decidido interferir em sua pequena façanha.",
  ui_story_31190601_173_dialog_content = "Além disso, dado o quão insignificante foi o seu crime, imaginei que eles só iriam prendê-lo por um dia ou dois com outros criminosos igualmente insignificantes.",
  ui_story_31190601_174_dialog_content = "Isso é muito mais seguro do que deixá-lo enlouquecer nas ruas de Umbraton, para ser honesto. Afinal, ninguém nesta prisão tem chance contra você.",
  ui_story_31190601_175_dialog_content = "(Ela pensou até agora... honestamente, ela é parcialmente responsável por esta situação...)",
  ui_story_31190601_176_dialog_content = "Eu nunca soube que você poderia ser tão fria, Allura. Isso dói!",
  ui_story_31190601_177_dialog_content = "Bem, como uma pessoa fria, acho que deveria dar meia-volta e ir embora agora.",
  ui_story_31190601_178_dialog_content = "E-Espere, não vá! Eu estava errado, agora você poderia, por favor, me tirar daqui? Estou morrendo de vontade de comer um pouco da comida da vovó agora!",
  ui_story_31190601_179_dialog_content = "Bem, eu sinto falta dele cozinhar também...",
  ui_story_31190601_180_dialog_content = "Se eu te levar de volta para Gannon City, eu poderia pedir uma refeição como pagamento por este pequeno trabalho dele.",
  ui_story_31190601_181_dialog_content = "Conta comigo!",
  ui_story_31190601_182_dialog_content = "Não nos sentamos juntos para uma das refeições lendárias de Gram há séculos. Isso realmente traz de volta memórias do Dunefire Strike...",
  ui_story_31190601_183_dialog_content = "Hoje, tenho que colocar em dia todas as refeições que perdi nos últimos dias!",
  ui_story_31190601_184_dialog_content = "Esta refeição poderia ter sido combinada com um Molho Quente Super Blazing...",
  ui_story_31190601_185_dialog_content = "Reviva...",
  ui_story_31190601_186_dialog_content = "Não vou desistir tão fácil! Uma vez que eu tenha comido o suficiente, vou continuar perseguindo o molho picante dos meus sonhos!",
  ui_story_31190601_187_dialog_content = "<color=#FFB400>Molho Quente Super Ardente</color>... Um dia, você será meu!",
  ui_story_31190602_1_dialog_content = "Este é um teste, bem como um jogo de alegria incomparável.",
  ui_story_31190602_2_dialog_content = "Gronru, Oficial de Tecnologia da Federação Illumina, convida você formalmente para participar deste jogo.",
  ui_story_31190602_3_dialog_content = "Não custa nada jogar e não há formulários para preencher. Tudo o que você precisa fazer é segurar minha mais recente tecnologia de ponta, e você ainda pode receber uma taxa de publicidade pelo seu esforço.",
  ui_story_31190602_4_dialog_content = "Com este dispositivo, você poderá proteger os fracos, bem como todos em Illumina e até mesmo o mundo.",
  ui_story_31190602_5_dialog_content = "Então, o que você está esperando? Entre em ação e junte-se à Patrulha Eclipsite agora!",
  ui_story_31190602_6_dialog_content = "Estou feliz que você está aqui, Senhorita Revy.",
  ui_story_31190602_7_dialog_content = "Espero que não se importe que eu pergunte, mas a carta não lhe parece suspeita?",
  ui_story_31190602_8_dialog_content = "Sim! Mas se eu puder proteger os fracos como um verdadeiro herói, estou disposto a participar deste jogo.",
  ui_story_31190602_9_dialog_content = "Então você terá que trocar para seu novo traje para o comercial.",
  ui_story_31190602_10_dialog_content = "Huh? Roupa nova?",
  ui_story_31190602_11_dialog_content = "Essas roupas... Elas são <size=45>ridiculamente pesadas!</size>",
  ui_story_31190602_12_dialog_content = "Sinto como se estivesse sufocando! Como vou proteger as crianças assim?!",
  ui_story_31190602_13_dialog_content = "Então, que papel você tem em mente para mim? Você pode me dizer, certo?",
  ui_story_31190602_14_dialog_content = "Você saberá assim que o oficial Gronru chegar!",
  ui_story_31190602_15_dialog_content = "Ei, PlayerName!",
  ui_story_31190602_16_dialog_content = "Revy? Então você é o outro artista, né?",
  ui_story_31190602_17_dialog_content = "Essas roupas ficaram realmente legais em você!",
  ui_story_31190602_18_dialog_content = "Sério? Porque eu me sinto como uma tartaruga presa em seu casco.",
  ui_story_31190602_19_dialog_content = "Cadê sua roupa nova?",
  ui_story_31190602_20_dialog_content = "Quem sabe? Tudo depende de Gronru, aparentemente.",
  ui_story_31190602_21_dialog_content = "Huh? Ei, olha aquele armário grande ali! Será que é lá que eles guardam as câmeras e outras coisas?",
  ui_story_31190602_22_dialog_content = "Segure! Mantenha suas mãos longe dos meus Materiais Experimentais de Grau S!",
  ui_story_31190602_23_dialog_content = "Ah, graças a Deus! Se isso desse errado, todo o comercial estaria arruinado!",
  ui_story_31190602_24_dialog_content = "Aham! Parece que todos estão presentes e contabilizados!",
  ui_story_31190602_25_dialog_content = "Heheh, agora posso finalmente revelar minha mais recente invenção! Tente não se assustar demais!",
  ui_story_31190602_26_dialog_content = "Deleite seus olhos com o Aspirador de Pó Eclipsite! Sinta-se à vontade para pular e gritar agora, se quiser!",
  ui_story_31190602_27_dialog_content = "Se isso me ajudar a matar Eclipsitas e proteger os fracos, então isso já é bom o suficiente para mim!",
  ui_story_31190602_28_dialog_content = "Espere, então sua \"última peça de tecnologia de ponta\" é apenas um aspirador de pó?!",
  ui_story_31190602_29_dialog_content = "Ei, você retira isso agora mesmo! É chamado de Aspirador de Pó Eclipsita, muito obrigado!",
  ui_story_31190602_30_dialog_content = "Como você pode ser tão ignorante?",
  ui_story_31190602_31_dialog_content = "Ei, é bem confortável na minha mão! Como eu uso isso?",
  ui_story_31190602_32_dialog_content = "Este foi aprimorado para se assemelhar ao seu Laminaltar. Quanto ao uso, explicarei logo antes de começarmos a filmar.",
  ui_story_31190602_33_dialog_content = "Vocês dois já deveriam ter entendido até agora, certo? Eu quero que vocês usem o Aspirador de Pó Eclipsita para me ajudar a gravar um vídeo promocional!",
  ui_story_31190602_34_dialog_content = "E somos os únicos dois atores?",
  ui_story_31190602_35_dialog_content = "Sim! Meu vídeo promocional não precisa de tantas pessoas.",
  ui_story_31190602_36_dialog_content = "(Na verdade, vocês são as únicas duas pessoas que apareceram... Todos os outros acharam que era uma pegadinha.)",
  ui_story_31190602_37_dialog_content = "Então, quem está interpretando o personagem principal?",
  ui_story_31190602_38_dialog_content = "Isso seria... Revy!",
  ui_story_31190602_39_dialog_content = "Então e quanto a mim?",
  ui_story_31190602_40_dialog_content = "Você vai interpretar o Eclipsite que embosca Revy, apenas para ser completamente destruído pelo Aspirador de Pó Eclipsite dela.",
  ui_story_31190602_41_dialog_content = "Eu objeção!",
  ui_story_31190602_42_dialog_content = "Rejeitado!",
  ui_story_31190602_43_dialog_content = "Acabei de lembrar de algo, Oficial Gronru. Não deveríamos fazer a maquiagem de Revy antes de começarmos a filmar?",
  ui_story_31190602_44_dialog_content = "Deixe isso comigo! Heeheehee, vai ser divertido!",
  ui_story_31190602_45_dialog_content = "Urgh—Isso parece realmente estranho.",
  ui_story_31190602_46_dialog_content = "Não se preocupe! Isso é material de primeira linha, mesmo que eu não faça ideia do que seja!",
  ui_story_31190602_47_dialog_content = "Acho que eu deveria cuidar disso, Oficial Gronru.",
  ui_story_31190602_48_dialog_content = "Olha, as narinas do Revy estão cheias de maquiagem agora.",
  ui_story_31190602_49_dialog_content = "<size=45>Ahhh—Atchim—</size>",
  ui_story_31190602_50_dialog_content = "De jeito nenhum, isso é muito divertido! Apenas me deixe fazer isso!",
  ui_story_31190602_51_dialog_content = "Um pouco mais aqui, um pouco mais ali, e pronto!",
  ui_story_31190602_52_dialog_content = "É perfeito! Até eu me surpreendo às vezes!",
  ui_story_31190602_53_dialog_content = "Hmm, acho que você deveria deixar Siobhan cuidar da maquiagem de Revy desta vez.",
  ui_story_31190602_54_dialog_content = "<color=#e8d9bb>Após uma segunda transformação, os dois atores ensaiam suas falas antes de aprenderem a usar o aspirador de pó.</color>",
  ui_story_31190602_55_dialog_content = "Três, dois, um, ação!",
  ui_story_31190602_56_dialog_content = "Me pergunto o quão bem meu novo aspirador de pó funciona?",
  ui_story_31190602_57_dialog_content = "Uau, é tão poderoso. Parece que... Uma arma de grau S logo no primeiro nível.",
  ui_story_31190602_58_dialog_content = "Essas linhas estão terríveis. Tem certeza de que isso está bem?",
  ui_story_31190602_59_dialog_content = "Não tem jeito. O oficial Gronru escreveu eles pessoalmente.",
  ui_story_31190602_60_dialog_content = "É hora da sua parte!",
  ui_story_31190602_61_dialog_content = "<size=45>Sibilo—</size>",
  ui_story_31190602_62_dialog_content = "Um Eclipsita? Prepare-se para morrer!",
  ui_story_31190602_63_dialog_content = "Ajoelhem-se diante do incrível poder do meu Aspirador de Pó Eclipsita!",
  ui_story_31190602_64_dialog_content = "(Aff, acho que devo me envolver um pouco mais nisso.)",
  ui_story_31190602_65_dialog_content = "(Huh? Eu não estou me movendo, então por que... Por que meu corpo está começando a...)",
  ui_story_31190602_66_dialog_content = "Aaaahhhh—Vai... Vai me sugar!",
  ui_story_31190602_67_dialog_content = "Tempo! Tempo! Gronru, corte!",
  ui_story_31190602_68_dialog_content = "Minhas calças! Minhas calças estão sendo sugadas!",
  ui_story_31190602_69_dialog_content = "Não pare agora! Continue!",
  ui_story_31190602_70_dialog_content = "<color=#e8d9bb>A sucção do aspirador de pó cria um poderoso redemoinho dentro da sala.</color>",
  ui_story_31190602_71_dialog_content = "<color=#e8d9bb>Rapidamente começa a sugar tudo à vista, incluindo o armário de Materiais Experimentais de Grau S do Gronru.</color>",
  ui_story_31190602_72_dialog_content = "Sibilo—",
  ui_story_31190602_73_dialog_content = "Graaaaaaahh!!",
  ui_story_31190602_74_dialog_content = "O que um Eclipsite está fazendo aqui?!",
  ui_story_31190602_75_dialog_content = "Continue filmando! Esta é a parte mais importante!",
  ui_story_31190602_76_dialog_content = "Você está falando sério?!",
  ui_story_31190602_77_option_content = "Direto Revy",
  ui_story_31190602_78_dialog_content = "Revy! Agora é a hora de usar bem aquele Aspirador de Eclipsitas!",
  ui_story_31190602_79_dialog_content = "Faça-o sentir a mesma dor e desespero que eu acabei de sentir!",
  ui_story_31190602_80_option_content = "Esconda-se atrás do Revy",
  ui_story_31190602_81_dialog_content = "Aquele Eclipsite... Está vindo direto para nós!",
  ui_story_31190602_82_dialog_content = "Ahhh...!",
  ui_story_31190602_83_dialog_content = "Droga! Por mais que eu queira lutar, vou ter que deixar isso para Revy.",
  ui_story_31190602_84_dialog_content = "A fonte de alimentação está boa e o ângulo também. Ativando o Aspirador de Pó Eclipsite!",
  ui_story_31190602_85_dialog_content = "Eu vou te proteger, PlayerName!",
  ui_story_31190602_86_dialog_content = "???",
  ui_story_31190602_87_dialog_content = "Sibilo—",
  ui_story_31190602_88_dialog_content = "Pare de resistir tanto, seu Eclipsita fedido!",
  ui_story_31190602_89_dialog_content = "Revy! Diminua o ângulo em quinze graus e mire nos pés dele, para que perca o equilíbrio!",
  ui_story_31190602_90_dialog_content = "Você é história, Eclipsite!",
  ui_story_31190602_91_dialog_content = "Graaaaaah—",
  ui_story_31190602_92_dialog_content = "E assim, nosso jovem herói protege a pessoa mais importante para ela.",
  ui_story_31190602_93_dialog_content = "Até mesmo um ameaçador Eclipsita não passa de um grão de poeira diante do poder de limpeza do Aspirador de Pó Eclipsita.",
  ui_story_31190602_94_dialog_content = "Você sonha em se tornar um herói aos olhos das outras pessoas? Deseja proteger seus entes queridos e derrotar os Eclipsitas com facilidade?",
  ui_story_31190602_95_dialog_content = "Então pegue o telefone agora mesmo, ligue para a linha direta do Laboratório de Pesquisa Illumina e faça seu pedido hoje!",
  ui_story_31190602_96_dialog_content = "Aspirador de Pó Eclipsite, ninguém pode recusá-lo após usá-lo.",
  ui_story_31190602_97_dialog_content = "Confie no Aspirador de Pó Eclipsita para fazer o trabalho.",
  ui_story_31190602_98_dialog_content = "Por favor, note: os pedidos só podem ser feitos entre 15h e 16h, pois Gronru está ocupado jogando o resto do tempo.",
  ui_story_31190602_99_dialog_content = "Corte—!",
  ui_story_31190602_100_dialog_content = "Isso foi perfeito! Eu estaria ligando para o laboratório agora mesmo se visse isso!",
  ui_story_31190602_101_dialog_content = "Você não concorda, Siobhan?",
  ui_story_31190602_102_dialog_content = "Um... Aham!",
  ui_story_31190602_103_dialog_content = "Ufa... estou derrotado.",
  ui_story_31190602_104_dialog_content = "Agora que a missão principal foi concluída, é hora de algumas missões secundárias!",
  ui_story_31190602_105_dialog_content = "Vamos tirar algumas fotos promocionais!",
  ui_story_31190602_106_dialog_content = "Antes de continuarmos, podemos por favor falar sobre aquele Eclipsite agora há pouco?! O que ele estava fazendo no seu laboratório?!",
  ui_story_31190602_107_dialog_content = "Eu precisava de algo para tornar sua performance um pouco mais realista, então contratei algumas pessoas para pegar um para mim.",
  ui_story_31190602_108_dialog_content = "Bem incrível, né? Minha invenção é tão boa que eu deveria solicitar uma patente.",
  ui_story_31190602_109_dialog_content = "Vou levar um! Quanto custa?",
  ui_story_31190602_110_dialog_content = "Hã? N-Não me diga que você realmente gosta dessa coisa, Revy?!",
  ui_story_31190602_112_dialog_content = "Isso tornará derrotar os Eclipsitas ainda mais fácil, o que significa que poderei proteger você ainda melhor. Isso deve me aproximar um passo de me tornar um verdadeiro herói!",
  ui_story_31190602_113_dialog_content = "Normalmente, eu cobraria por isso, mas vou abrir uma exceção desta vez.",
  ui_story_31190602_114_dialog_content = "Certifique-se de fazer um bom trabalho promovendo meu Aspirador de Pó Eclipsita, Revy!",
  ui_story_31190602_115_dialog_content = "Deixa comigo."
}
